const D = { density:.5, scale:1, energy:.55, speed:1, wind:.5, bloom:.5, hue:110, x:.5, y:.94, style:'ink', act:'grow', seed:0 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const md=(a,n)=>((a%n)+n)%n, clp=(v,a,b)=>Math.max(a,Math.min(b,v)), TAU=Math.PI*2, RAD=Math.PI/180;
const fr=i=>{const s=Math.sin(i*127.1+P.seed*311.7)*43758.5453;return s-Math.floor(s);};
if(S.lastBeat==null||K.beat<S.lastBeat)S.lastBeat=K.beat; S.lastBeat=K.beat;

const W=width,Hh=height,u=Math.min(W,Hh);
const style=P.style, dens=clp(P.density,0,1), en=clp(P.energy,0,1)*(.5+.6*K.intensity);
const spI=P.seed%4;                                     // species by seed
const maxIt=[5,3,5,5][spI];                             // bushy species blows up past 3
const iters=Math.min(maxIt, 3+Math.round(dens*2));      // 3..5 complexity, clamped

// ---- seed-deterministic L-system string (cached) ----
const lkey=P.seed+'|'+iters;
if(S.lkey!==lkey){
  S.lkey=lkey;
  const SP=[
    {ax:'X', rX:'F+[[X]-X]-F[-FX]+X', rF:'FF', ang:22},   // classic fern
    {ax:'F', rX:'', rF:'FF+[+F-F-F]-[-F+F+F]', ang:24},   // bushy
    {ax:'X', rX:'F[+X]F[-X]+X',        rF:'FF', ang:20},   // sparse reach
    {ax:'X', rX:'F[+X][-X]FX',         rF:'FF', ang:26}    // symmetric tree
  ][spI];
  let s=SP.ax;
  for(let g=0;g<iters;g++){ let n=''; for(let i=0;i<s.length;i++){ const c=s[i]; n+= c==='X'? SP.rX : c==='F'? SP.rF : c; } s=n; }
  S.str=s; S.angBase=SP.ang+(fr(9)*8-4);                 // seed jitter on branch angle
  // count F segments to normalise length
  let f=0; for(let i=0;i<s.length;i++) if(s[i]==='F') f++;
  S.fCount=f;
  // pick blossom node indices deterministically (which ']' get a flower)
  S.blm=[]; let bi=0; for(let i=0;i<s.length;i++){ if(s[i]===']'){ S.blm.push(fr(bi*7.3+1)); bi++; } }
}
const str=S.str, fCount=Math.max(1,S.fCount);

// ---- background (cached, size+seed+style keyed) — genart owns bg ----
const bkey=W+'x'+Hh+'|'+P.seed+'|'+style;
if(S.bkey!==bkey){
  S.bkey=bkey;
  const g=createGraphics(W,Hh); g.colorMode(g.HSB,360,100,100,100); g.noStroke();
  if(style==='blueprint'){ g.fill(210,72,26); g.rect(0,0,W,Hh);
    g.stroke(200,30,60,16); g.strokeWeight(1); const gs=u*0.05;
    for(let x=0;x<=W;x+=gs) g.line(x,0,x,Hh); for(let y=0;y<=Hh;y+=gs) g.line(0,y,W,y);
  } else if(style==='neon'){ g.fill(260,55,7); g.rect(0,0,W,Hh);
    for(let i=0;i<50;i++){ g.fill(260,40,10+fr(i*3)*6,20); g.circle(fr(i*1.7)*W,fr(i*2.9)*Hh,u*0.02*(1+fr(i))); }
  } else if(style==='charcoal'){ g.fill(30,6,20); g.rect(0,0,W,Hh);
    for(let i=0;i<70;i++){ g.fill(30,4,14+fr(i)*12,10); g.circle(fr(i*1.3)*W,fr(i*2.1)*Hh,u*(0.05+0.14*fr(i*3))); }
  } else { // ink: warm paper + mottle + faint vignette
    g.fill(40,12,86); g.rect(0,0,W,Hh);
    for(let i=0;i<70;i++){ g.fill(40,14,82+fr(i)*6,8); g.circle(fr(i*1.9)*W,fr(i*3.3)*Hh,u*(0.05+0.16*fr(i*5))); }
    g.fill(40,16,64,14); g.rect(0,0,W,Hh*0.16); g.rect(0,Hh*0.88,W,Hh*0.12);
  }
  S.bg=g;
}
image(S.bg,0,0);

// ---- live turtle draw ----
const ink = style==='ink', blue=style==='blueprint', neon=style==='neon', char=style==='charcoal';
const hue=md(P.hue,360);
// wind: whole-plant sway (continuous, real-time, never re-phases) + audio gust
const windAmp=(0.05+0.20*clp(P.wind,0,1))*(0.5+0.9*en);
const sway=windAmp*(Math.sin(K.t*(0.6+0.5*clp(P.speed,0.2,4)))*0.7 + Math.sin(K.t*1.7+1.3)*0.3) + A.lowmid*0.10*en;
// growth reveal (act dramaturgy)
let grow;
const gp=K.t*0.03*clp(P.speed,0.2,4);
if(P.act==='wither'){ grow=0.35+0.65*(0.5+0.5*Math.sin(gp*TAU)); }          // grows & recedes
else if(P.act==='pulse'){ grow=0.55+0.45*Math.sin(gp*TAU*1.5); grow=clp(grow,0,1); } // breathing tips
else { const ph=(gp%1); grow=clp(ph<0.5? ph*2 : 1, 0.12,1); }               // grow-and-hold
const revealN=Math.min(1300, Math.max(8, Math.floor(fCount*grow)));  // cap drawn segs for fps

// turtle length so plant roughly fits, scaled
const lenTab={3:0.075,4:0.045,5:0.026};
let len=u*(lenTab[iters]||0.03)*clp(P.scale,0.3,2.4)*1.15;
const turn=(S.angBase)*RAD;
const bx=P.x*W, by=P.y*Hh;

let x=bx, y=by, ang=-Math.PI/2 + sway*0.6;   // base sway tilts whole plant
const st=[]; let depth=0, drawn=0;

// stroke base colour by style
let sw0=Math.max(1.1, u*0.006*clp(P.scale,0.3,2.4));
noFill();
if(neon){ blendMode(ADD); }
for(let i=0;i<str.length && drawn<revealN;i++){
  const c=str[i];
  if(c==='F'){
    // per-segment micro wind grows with height & depth (secondary flutter)
    const fl=(0.015+0.03*clp(P.wind,0,1))*Math.sin(K.t*2.2 + depth*0.7 + drawn*0.02)*(0.4+en);
    ang+=fl;
    const x2=x+Math.cos(ang)*len, y2=y+Math.sin(ang)*len;
    const taper=clp(1-depth*0.14,0.18,1);
    if(blue){ stroke(200,18,96,72); strokeWeight(Math.max(0.8,sw0*0.5*taper)); }
    else if(neon){ stroke(hue,80,100, 26+40*taper); strokeWeight(sw0*(0.6+1.4*taper)); }
    else if(char){ stroke(30,6,96-60*taper,22); strokeWeight(sw0*(1+2.2*taper)); }
    else { // ink: dark tapered brush, drier (lighter) toward tips
      stroke(md(hue+8,360), 40+18*taper, 14+34*(1-taper), 82); strokeWeight(sw0*(0.5+2.6*taper)); }
    line(x,y,x2,y2);
    x=x2; y=y2; drawn++;
  } else if(c==='+'){ ang+=turn+sway*0.15; }
  else if(c==='-'){ ang-=turn-sway*0.15; }
  else if(c==='['){ st.push([x,y,ang,depth]); depth++; }
  else if(c===']'){ const p=st.pop(); if(p){ x=p[0]; y=p[1]; ang=p[2]; depth=p[3]; } }
}
if(neon) blendMode(BLEND);

// ---- blossoms at revealed branch tips (bloom waxes over sections) ----
const bloomAmt=clp(P.bloom,0,1)*(0.35+0.9*K.intensity);
const bhue=md(hue+ (ink?250:40),360);                    // vermilion-ish against green ink
// second cheap pass: walk again, place blossoms at ']' whose token passed reveal
{
  let bx2=bx, by2=by, a2=-Math.PI/2+sway*0.6, dr=0, dp=0, bIdx=0; const s2=[];
  noStroke();
  for(let i=0;i<str.length && dr<revealN;i++){
    const c=str[i];
    if(c==='F'){ const fl=(0.015+0.03*clp(P.wind,0,1))*Math.sin(K.t*2.2 + dp*0.7 + dr*0.02)*(0.4+en);
      a2+=fl; bx2+=Math.cos(a2)*len; by2+=Math.sin(a2)*len; dr++; }
    else if(c==='+'){ a2+=turn+sway*0.15; }
    else if(c==='-'){ a2-=turn-sway*0.15; }
    else if(c==='['){ s2.push([bx2,by2,a2,dp]); dp++; }
    else if(c===']'){
      const th=S.blm[bIdx]!=null?S.blm[bIdx]:0.5; bIdx++;
      if(th < bloomAmt){
        const puls=1+0.5*K.pulse+1.2*A.bass;
        const r=u*(0.006+0.012*clp(P.scale,0.3,2.4))*puls*(0.6+0.8*th);
        if(neon){ blendMode(ADD); fill(bhue,70,100,55); circle(bx2,by2,r*1.8); blendMode(BLEND); }
        else if(blue){ noFill(); stroke(200,20,98,80); strokeWeight(1); circle(bx2,by2,r*1.6); noStroke(); }
        else if(ink){ fill(bhue,78,84,72); circle(bx2,by2,r*1.5); fill(bhue,60,96,40); circle(bx2,by2,r*0.7); }
        else { fill(bhue,30,92,60); circle(bx2,by2,r*1.4); }
      }
      const p=s2.pop(); if(p){ bx2=p[0]; by2=p[1]; a2=p[2]; dp=p[3]; }
    }
  }
}

blendMode(BLEND); drawingContext.shadowBlur=0; noStroke();
